referenceFixTemplate:
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    ofstream out("note.txt");
    out << "{p1}" << endl;
    out << "{p2}" << endl;
    out.close();

    ifstream in("note.txt");
    string line;
    while (getline(in, line)) {
        cout << line << endl;
    }
    return 0;
}
